<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { Activity, Cable, CircleAlert, Cpu, Download, Moon, Play, RefreshCw, Save, Settings2, ShieldCheck, Square, Sun, Terminal, Trash2 } from 'lucide-vue-next';
import { api, desktop, parameterDescriptors, validateParameterMap, type ParameterDescriptor, type Batch, type Endpoint, type Snapshot, type Telemetry } from './api';
import TelemetryChart from './TelemetryChart.vue';
import ControlBar from './ControlBar.vue';
const tabs=['运行监控','参数配置','自动整定','数据记录'];const tab=ref(tabs[0]);const controlMode=ref<'current'|'velocity'|'open'>('current');const setpoint=ref(1);const openVoltage=ref(1);const dark=ref(false);const source=ref<'simulator'|'serial'>('simulator');const ports=ref<Endpoint[]>([]);const port=ref('');const snap=ref<Snapshot>(api.getSnapshot());const hist=ref<Telemetry[]>([]);const logs=ref<{t:string;text:string;level:string}[]>([]);const params=ref<Record<string,number>>({});const descriptors=ref<ParameterDescriptor[]>(parameterDescriptors);const baseline=ref<Record<string,number>>({});const recording=ref(false);const busy=ref(false);const fileInput=ref<HTMLInputElement>();const plot=ref<'phase'|'dq'|'velocity'|'vbus'|'temperature'>('phase');const table=ref(false);const paused=ref(false);let touch:number|undefined;let session=0;
const addLog=(text:string,level='info')=>{logs.value.push({t:new Date().toLocaleTimeString('zh-CN',{hour12:false}),text,level});if(logs.value.length>200)logs.value.shift()};const latest=computed(()=>snap.value.telemetry??undefined);const rpm=computed(()=>latest.value?latest.value.velocity*60/(2*Math.PI):null);const stale=computed(()=>snap.value.packetAgeMs!==null&&snap.value.packetAgeMs>500);const faultNames=computed(()=>[{bit:0,name:'过流'},{bit:1,name:'电流残差'},{bit:2,name:'欠压'},{bit:3,name:'过压'},{bit:4,name:'过温'},{bit:5,name:'堵转'},{bit:6,name:'传感器'},{bit:7,name:'控制超时'},{bit:8,name:'无效命令'}].filter(f=>((latest.value?.faults??0)&(1<<f.bit))!==0).map(f=>f.name));const groups=computed(()=>Array.from(new Set(descriptors.value.map(p=>p.group))));const dirty=computed(()=>JSON.stringify(params.value)!==JSON.stringify(baseline.value));
function onBatch(b:Batch){const wasRecording=recording.value;snap.value=b.snapshot;recording.value=b.snapshot.recording;if(wasRecording&&!recording.value&&b.snapshot.recordCount>=12000)addLog('主机端录制达到 12,000 帧上限，录制已停止','warning');if(!paused.value){hist.value.push(...b.samples);if(hist.value.length>600)hist.value.splice(0,hist.value.length-600)}}
async function connect(){busy.value=true;const token=++session;try{snap.value=await api.connect(source.value,port.value,b=>{if(token===session)onBatch(b)});addLog(source.value==='simulator'?'模拟器已连接；界面数据明确标注为模拟':'加密桥接连接已建立并完成设备握手','success');descriptors.value=await api.parameter_descriptors();await refreshParams()}catch(e){addLog(String(e),'error')}finally{busy.value=false}}
async function disconnect(){session++;await api.disconnect();snap.value=api.getSnapshot();hist.value=[];recording.value=false;addLog('已断开连接')}
async function scan(){try{ports.value=await api.discover();port.value=ports.value[0]?.id??'';addLog(`发现 ${ports.value.length} 个桥接端点`)}catch(e){addLog(String(e),'error')}}
function replyText(text:string){return ({applied:'设备已确认执行',accepted:'设备已接受请求，请继续查看状态',released:'控制权已释放，设备已停止','not-ready':'设备遥测暂不可用'}[text]??text)}
async function cmd(c:string):Promise<boolean>{try{const r=await api.command(c);snap.value=api.getSnapshot();addLog(replyText(r),'success');return true}catch(e){addLog(String(e),'error');return false}}
async function confirmed(c:string,prompt:string){if(window.confirm(prompt))await cmd(c)}
async function applyTarget():Promise<boolean>{if(!snap.value.connected||!snap.value.controlled||!snap.value.telemetry){addLog('等待有效遥测，当前不能设置控制目标','error');return false}const value=setpoint.value, state=snap.value.telemetry.state;const compatible=state===1||controlMode.value==='open'&&state===2||controlMode.value==='current'&&state===3||controlMode.value==='velocity'&&state===4;if(!compatible){addLog('目标模式与当前运行状态不匹配','error');return false}if(!Number.isFinite(value)||controlMode.value==='current'&&Math.abs(value)>Math.min(params.value['current-limit']??50,50)||controlMode.value==='velocity'&&Math.abs(value)>(params.value['maximum-velocity']??1000)||controlMode.value==='open'&&(!Number.isFinite(openVoltage.value)||Math.abs(value)>(params.value['maximum-open-loop-velocity']??10000)||Math.abs(openVoltage.value)>(latest.value?.vbus??0)/2)){addLog('目标值超出有限值或当前参数/母线限制','error');return false}const command=controlMode.value==='current'?`iq ${value}`:controlMode.value==='velocity'?`velocity ${value}`:`open ${value} ${openVoltage.value}`;return await cmd(command)}
async function enableControl(){if(!window.confirm(`确认使能${controlMode.value==='current'?'电流控制':controlMode.value==='velocity'?'速度控制':'开环控制'}？请先确认机械与电气安全。`))return;if((snap.value.telemetry?.state??1)!==1){addLog('电机必须处于空闲状态才能使能','error');return}if(!await applyTarget())return;if(!await cmd(`enable ${controlMode.value}`)){await cmd('disable');addLog('使能未确认，已请求停用输出','warning')}}
async function factoryReset(){if(window.confirm('确认执行设备出厂重置？此操作可能覆盖设备持久配置。')&&await cmd('param factory-reset'))await refreshParams()}
async function paramAction(command:string){if(await cmd(command)&&['param load','param defaults'].includes(command))await refreshParams()}
async function refreshParams(){try{params.value=await api.read_parameters();baseline.value={...params.value}}catch(e){addLog(String(e),'error')}}
async function applyParams(){if(!snap.value.controlled||!snap.value.connected)return;let ok=0;for(const d of descriptors.value){if(params.value[d.name]===baseline.value[d.name])continue;try{const answer=await api.write_parameter(d.name,params.value[d.name]!);addLog(`${d.label}: ${answer}`,'success');ok++}catch(e){addLog(`${d.label} 写入失败：${String(e)}`,'error')}}await refreshParams();addLog(`逐项写入结束，成功请求 ${ok} 项；以上逐项结果为准`)}
async function record(){try{const on=!recording.value;await api.set_recording(on);if(!desktop){recording.value=on;snap.value=api.getSnapshot()}addLog(on?'开始主机端录制':'主机端录制已停止')}catch(e){addLog(String(e),'error')}}function browserDownload(name:string,body:string,type:string){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function exportCsv(){try{const csv=await api.export_csv();if(desktop){const path=await api.save_export('csv',csv);addLog(`已导出主机端 CSV：${path}`,'success')}else{browserDownload('foc-telemetry.csv',csv,'text/csv');addLog('已导出主机端 CSV','success')}}catch(e){addLog(`CSV 导出失败：${String(e)}`,'error')}}
async function exportConfig(){try{const payload={version:1,model:'FOC',parameters:params.value};const body=JSON.stringify(payload,null,2);if(desktop){const path=await api.save_export('json',body);addLog(`已导出参数文件：${path}`,'success')}else{browserDownload('foc-parameters-v1.json',body,'application/json');addLog('已导出参数文件','success')}}catch(e){addLog(`参数导出失败：${String(e)}`,'error')}}async function importConfig(e:Event){const input=e.target as HTMLInputElement;try{const f=input.files?.[0];if(!f)return;if(f.size>65536)throw Error('文件超过 64 KB');const x=JSON.parse(await f.text());if(x.version!==1||x.model!=='FOC'||!x.parameters||typeof x.parameters!=='object')throw Error('仅接受 version=1 且 model=FOC 的参数文件');validateParameterMap(x.parameters);params.value={...x.parameters};addLog('配置已导入编辑区；尚未写入设备','success')}catch(err){addLog(String(err),'error')}finally{input.value=''}}
function esc(v:number|undefined,n=2){return v===undefined?'—':v.toFixed(n)}
onMounted(()=>{addLog(desktop?'桌面环境就绪；真实串口仅通过加密桥接连接':'浏览器模式仅支持模拟器，硬件扫描不可用');touch=window.setInterval(()=>{if(snap.value.connected)void api.touch().catch(e=>addLog(String(e),'error'))},150);if(!desktop)void connect()});onUnmounted(()=>{clearInterval(touch);session++;void api.disconnect()});
</script>
<template><div class="app" :class="{dark}"><header class="titlebar"><div class="brand-icon"><Activity :size="19"/></div><strong>FOC Studio</strong><span class="version">v0.1</span><span class="title-caption">三相电机控制工作台</span><span class="spacer"></span><span class="mode-badge" :class="{sim:!snap.connected||snap.source==='simulator'}">{{snap.connected?(snap.source==='simulator'?'模拟器':'C3 加密桥接'):desktop?(source==='simulator'?'桌面模拟器':'C3 加密桥接'):'浏览器模拟器'}}</span><button class="icon-btn" @click="dark=!dark" :aria-label="dark?'浅色主题':'深色主题'"><Sun v-if="dark"/><Moon v-else/></button></header>
<nav class="topnav"><div class="tabs"><button v-for="t in tabs" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}</button></div><div class="nav-meta"><span class="tiny-dot" :class="{green:snap.connected}"></span>{{snap.connected?'已连接':'离线'}} <span class="divider-v"></span><span>FOC · 100 kHz / 200 ns*</span></div></nav>
<div class="layout"><main class="main"><div class="page-heading"><div><div class="eyebrow">MOTOR CONTROL / SESSION</div><h1>{{tab==='运行监控'?'运行监控':tab==='参数配置'?'参数配置':tab==='自动整定'?'自动整定':'数据记录'}}</h1><p>{{tab==='运行监控'?'观察电机遥测与状态；图表暂停不影响采集或连接保活。':'操作仅在设备就绪且取得控制权后开放。'}}</p></div><span class="safe-note"><ShieldCheck :size="15"/>软件保护 · 未实机验证</span></div>
<template v-if="tab==='运行监控'"><div class="metrics"><article class="metric"><span>机械转速</span><b>{{rpm===null?'—':rpm.toFixed(0)}}<small>rpm</small></b><em>遥测 velocity × 60 / 2π</em></article><article class="metric"><span>相电流 Ia / Ib / Ic</span><b>{{esc(latest?.ia)}} / {{esc(latest?.ib)}} / {{esc(latest?.ic)}}<small>A</small></b><em>20 Hz 通道遥测</em></article><article class="metric"><span>母线电压</span><b>{{esc(latest?.vbus)}}<small>V</small></b><em>设备采样值</em></article><article class="metric"><span>温度</span><b>{{esc(latest?.temperature,1)}}<small>°C</small></b><em>设备估算/遥测值</em></article></div>
<section class="card chart-card"><div class="card-heading"><div class="section-title"><Activity/><strong>{{snap.telemetry?'实时遥测':'历史遥测'}}</strong><span class="subtle-tag">20 Hz</span></div></div><TelemetryChart :samples="hist" :dark="dark" v-model:plot="plot" v-model:paused="paused" v-model:table="table"/></section>
<section class="card status-card"><div class="status-heading"><div class="section-title"><Cpu/><strong>控制状态</strong></div><button class="secondary" :disabled="!snap.connected||!snap.controlled||!(snap.telemetry?.faults)" @click="cmd('clear')">清除故障</button></div><div class="state-grid"><div><span>状态</span><b>{{snap.telemetry?(['校准中','空闲','开环','电流控制','速度控制','故障'][snap.telemetry.state]??'未知'):'遥测未就绪'}}</b></div><div><span>故障位</span><b>{{snap.telemetry?.faults??'—'}}</b><small>{{snap.telemetry?faultNames.length?faultNames.join(' · '):'无活动故障':'遥测未就绪'}}</small></div><div><span>Id / Iq</span><b>{{esc(latest?.id)}} / {{esc(latest?.iq)}} A</b></div><div><span>丢弃帧</span><b>{{snap.dropped}}</b></div></div><p class="footnote">传感器故障位仅表示通用传感器异常，不保证检测所有静止断线故障。</p></section></template>
<section v-else-if="tab==='参数配置'" class="card parameter-card"><div class="card-heading"><div class="section-title"><Settings2/><strong>固件参数 · 43 项</strong><span class="subtle-tag" :class="{changed:dirty}">{{dirty?'未应用编辑':'已读回'}}</span></div><div class="heading-actions"><button class="soft-button" @click="refreshParams" :disabled="!snap.connected">读取</button><button class="soft-button" @click="applyParams" :disabled="!snap.connected||!snap.controlled||snap.telemetry?.state!==1||!dirty">逐项写入并读回</button></div></div><div class="parameter-groups"><section v-for="group in groups" :key="group"><h3>{{group}}</h3><label v-for="d in descriptors.filter(p=>p.group===group)" :key="d.name" class="param-row"><span>{{d.label}}<small>{{d.name}} · {{d.kind}}<b v-if="d.startupOnly">启动时生效</b></small></span><input type="number" :min="d.min" :max="d.max" :step="d.kind==='f32'?'any':1" v-model.number="params[d.name]" :disabled="!snap.connected"><em>{{d.unit||'—'}}</em></label></section></div><footer class="param-footer">参数逐项非原子写入；失败项与读回结果见日志。保存到持久存储与 RAM 应用是不同操作。<button @click="exportConfig">导出 JSON</button><button @click="fileInput?.click()">导入编辑区</button><input ref="fileInput" type="file" accept="application/json,.json" hidden @change="importConfig"><button @click="paramAction('param load')" :disabled="!snap.connected||!snap.controlled||snap.telemetry?.state!==1">设备加载</button><button @click="paramAction('param defaults')" :disabled="!snap.connected||!snap.controlled||snap.telemetry?.state!==1">恢复默认</button><button @click="factoryReset" :disabled="!snap.connected||!snap.controlled||snap.telemetry?.state!==1">出厂重置</button><button @click="cmd('param save')" :disabled="!snap.connected||!snap.controlled||snap.telemetry?.state!==1"><Save :size="15"/>保存到设备</button></footer></section>
<section v-else-if="tab==='自动整定'" class="card extra-card"><div class="eyebrow">AUTOTUNE</div><h2>自动整定</h2><p>整定命令由固件/桥接端执行；浏览器模拟器不实现整定算法。启动前需确认电机及供电环境安全；停止为整定停止命令，不是硬件急停。</p><div class="tune-status">当前状态 <strong>{{snap.autotune}}</strong></div><div class="button-row"><button class="primary" :disabled="!desktop||!snap.connected||!snap.ready||!snap.controlled" @click="confirmed('autotune start','确认启动自动整定？请确认机械负载与限流措施已就绪。')"><Play :size="16"/>确认并启动</button><button class="secondary" :disabled="!desktop||!snap.connected" @click="cmd('autotune stop')"><Square :size="16"/>停止整定</button><button class="secondary" :disabled="!desktop||!snap.connected" @click="cmd('autotune status')">刷新状态</button></div></section>
<section v-else class="card extra-card"><div class="eyebrow">CAPTURED TELEMETRY</div><h2>{{snap.recordCount.toLocaleString()}} <small>帧已记录</small></h2><p>主机端录制由主机保留，与图表显示暂停无关；CSV 导出可在断开后进行，帧数与丢弃数依设备端快照。</p><div class="button-row"><button class="primary" :disabled="!snap.connected" @click="record">{{recording?'停止录制':'开始主机端录制'}}</button><button class="secondary" :disabled="snap.recordCount===0" @click="exportCsv"><Download :size="16"/>导出主机 CSV</button></div></section>
</main><aside class="sidebar"><section class="card connection-card"><div class="card-heading"><div class="section-title"><Cable/><strong>连接与控制权</strong></div><span class="subtle-tag">{{snap.ready?'READY':'OFFLINE'}}</span></div><div class="connection-body"><div class="transport-grid"><button :class="{selected:source==='simulator'}" :disabled="snap.connected" @click="source='simulator'"><Cpu/>模拟器</button><button :class="{selected:source==='serial'}" :disabled="snap.connected||!desktop" @click="source='serial'"><Cable/>C3 加密桥接</button></div><p class="connection-help">{{desktop?'真实连接仅通过桥接握手并确认 secure=1 后开放。':'浏览器不能连接硬件；请在桌面端选择真实桥接。'}}</p><template v-if="source==='serial'"><div class="endpoint-row"><select v-model="port" :disabled="snap.connected"><option value="">选择桥接端口</option><option v-for="p in ports" :key="p.id" :value="p.id">{{p.name}}</option></select><button class="refresh" @click="scan" :disabled="!desktop||snap.connected"><RefreshCw/></button></div></template><button class="connect-button" :disabled="busy||(!snap.connected&&source==='serial'&&!port)" @click="snap.connected?disconnect():connect()">{{busy?'连接中…':snap.connected?'断开连接':'连接'}}</button><div class="divider"></div><div class="identity"><span>设备身份</span><b>{{snap.identity||'—'}}</b><span>链路</span><b>{{snap.bridge||'—'}}</b><span>遥测时效</span><b :class="{warning:stale}">{{snap.packetAgeMs===null?'—':`${snap.packetAgeMs} ms`}}</b></div><p v-if="snap.error" class="error-box"><CircleAlert/>{{snap.error}}</p><div class="control-box"><div><strong>{{snap.controlled?'控制权已获取':'未获取控制权'}}</strong><small>获取控制权不会使能电机</small></div><button class="soft-button" v-if="!snap.controlled" :disabled="!snap.connected||!snap.ready" @click="cmd('claim')">获取控制权</button><button class="secondary" v-else @click="cmd('release')">释放</button></div></div></section>
<section class="card session-card"><div class="section-title"><ShieldCheck/><strong>设备与安全信息</strong></div><dl><div><dt>来源</dt><dd>{{snap.source||'未连接'}}</dd></div><div><dt>固件状态</dt><dd>{{snap.connected?'握手就绪':'—'}}</dd></div><div><dt>PWM 配置</dt><dd>100 kHz · 200 ns*</dd></div><div><dt>验证状态</dt><dd>未进行板级验证</dd></div></dl></section><section class="card logs-card"><div class="card-heading"><div class="section-title"><Terminal/><strong>运行日志</strong><span class="log-count">{{logs.length}}</span></div><button class="icon-btn" @click="logs=[]" aria-label="清空日志"><Trash2/></button></div><div class="log-content"><div v-for="(l,i) in logs.slice().reverse()" :key="i" class="log-entry" :class="l.level"><time>{{l.t}}</time><span>{{l.text}}</span></div><p v-if="!logs.length" class="empty-logs">暂无日志</p></div></section><div class="sidebar-bottom"><span class="tiny-dot" :class="{green:snap.connected}"></span>{{stale?'遥测已过期':snap.connected?'通道在线':'等待连接'}}</div></aside></div>
<footer class="bottom-bar"><div class="bottom-info"><span class="tiny-dot" :class="{green:snap.connected}"></span>{{snap.connected?(snap.controlled?'控制权已获取':'设备已连接 · 尚未取得控制权'):'离线'}}<span class="divider-v"></span>使能前请确认电机安全固定与电源限流</div><ControlBar :connected="snap.connected" :ready="snap.ready" :controlled="snap.controlled" :idle="snap.telemetry?.state===1" v-model:mode="controlMode" v-model:setpoint="setpoint" v-model:open-voltage="openVoltage" @target="applyTarget" @enable="enableControl" @disable="cmd('disable')"/><small>*固件配置值；100 kHz 与 200 ns 尚未板级验证。停用不是硬件急停。</small></footer></div></template>
